SELECT es.* FROM employee_event_support es LEFT JOIN employee e ON es.employee_id = e.employee_id WHERE e.employee_id = #{employeeId}
AND ( e.name like concat('%', #{keyword}, '%') or e.employee_no like concat('%', #{keyword}, '%') )
ORDER BY es.created_at DESC

